const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sakha = ee.FeatureCollection("FAO/GAUL/2015/level1")
    .filter(ee.Filter.eq('ADM1_NAME', 'Sakha (Yakutiya)'))
    .first()
    .geometry();

  const startDate = '2021-06-01';
  const endDate = '2021-08-31';
  const scale = 1000; // Resolution for area calculation in meters
  const targetHectares = 6 * 1e6; // 6 million hectares

  // 2. Data Acquisition & Check
  const modisBurnedArea = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate(startDate, endDate)
    .filterBounds(sakha);

  const modisSize = await modisBurnedArea.size().getInfo();
  if (modisSize === 0) {
    console.log(`No MODIS MCD64A1 images found for Sakha during ${startDate} to ${endDate}.`);
    console.log("C1");
    return;
  }

  const hansenForest = ee.Image('UMD/hansen/global_forest_change_2022_v1_10')
    .select('treecover2000'); // Use treecover2000 for forest definition

  // Define forest as pixels with > 10% tree cover in 2000
  const forestMask = hansenForest.gt(10);

  // Function to process each image and calculate burned forest area
  const calculateBurnedForest = function(image) {
    // Burned area mask: where BurnDate > 0
    const burnedMask = image.select('BurnDate').gt(0);

    // Combine burned mask with forest mask
    const burnedForestPixels = burnedMask.and(forestMask);

    // Calculate area of burned forest pixels (in square meters)
    // Reduce the image to get a sum of pixel areas. Each pixel is 250m x 250m.
    // MODIS MCD64A1 resolution is 500m, but `pixelArea()` accounts for it.
    const area = burnedForestPixels.multiply(ee.Image.pixelArea());

    // Sum the area within the Sakha geometry
    const burnedForestAreaSqM = area.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: sakha,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326', // Use WGS84 for consistency or allow GEE to choose
    }).get('BurnDate'); // Get the sum from the 'BurnDate' band (which was multiplied by pixelArea)

    return image.set('burnedForestAreaSqM', burnedForestAreaSqM);
  };

  // Map the function over the collection
  const processedCollection = modisBurnedArea.map(calculateBurnedForest);

  // Get all burned forest area values
  const burnedAreasSqMList = await processedCollection.aggregate_array('burnedForestAreaSqM').getInfo();

  // Sum all monthly burned areas to get the total for the summer
  const totalBurnedForestAreaSqM = burnedAreasSqMList.reduce((acc, val) => acc + (val || 0), 0);

  if (totalBurnedForestAreaSqM === 0) {
    console.log("No valid burned forest pixels found after processing and masking.");
    console.log("C2");
    return;
  }

  // Convert square meters to hectares
  const totalBurnedForestAreaHectares = totalBurnedForestAreaSqM / 10000; // 1 hectare = 10,000 sq meters

  // 4. Validation & Final Answer
  if (totalBurnedForestAreaHectares === null || isNaN(totalBurnedForestAreaHectares)) {
    console.log("Calculation resulted in an invalid value (null/NaN).");
    console.log("C3");
    return;
  }

  const totalBurnedForestAreaMillionHectares = totalBurnedForestAreaHectares / 1e6;

  console.log(`Summer 2021 (Jun-Aug) Burned Forest Area in Sakha: ${totalBurnedForestAreaMillionHectares.toFixed(2)} million hectares.`);
  console.log(`Target: ${targetHectares / 1e6} million hectares.`);

  if (totalBurnedForestAreaHectares >= targetHectares) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
